#include "robot_profile.h"
#include <math.h>
static bool pin_ok(int p){return p>=-1&&p<=48;}
robot_profile_error_t robot_profile_validate(const robot_profile_t*p){if(!p||p->schema_version!=ROBOT_PROFILE_SCHEMA_VERSION)return ROBOT_PROFILE_BAD_SCHEMA;if(!p->endpoint_count||p->endpoint_count>ROBOT_PROFILE_MAX_ENDPOINTS||!p->rs485.drive_count||p->rs485.drive_count>ROBOT_PROFILE_MAX_DRIVES)return ROBOT_PROFILE_BAD_COUNT;if(!pin_ok(p->rs485.tx_pin)||!pin_ok(p->rs485.rx_pin)||!pin_ok(p->rs485.rts_pin)||!pin_ok(p->rc_rx_pin))return ROBOT_PROFILE_BAD_PIN;int pins[8]={p->rs485.tx_pin,p->rs485.rx_pin,p->rs485.rts_pin,p->rc_rx_pin,p->steering_servo_pins[0],p->steering_servo_pins[1],p->steering_servo_pins[2],p->steering_servo_pins[3]};size_t n=p->steering_servos_enabled?8:4;for(size_t i=0;i<n;i++)if(pins[i]>=0)for(size_t j=i+1;j<n;j++)if(pins[i]==pins[j])return ROBOT_PROFILE_PIN_CONFLICT;if(!isfinite(p->wheelbase_m)||!isfinite(p->track_width_m)||!isfinite(p->wheel_radius_m)||!isfinite(p->max_wheel_rpm)||p->wheelbase_m<=0||p->track_width_m<=0||p->wheel_radius_m<=0||p->max_wheel_rpm<=0)return ROBOT_PROFILE_BAD_GEOMETRY;for(size_t i=0;i<p->endpoint_count;i++){const robot_endpoint_profile_t*e=&p->endpoints[i];if(!e->name||e->drive_index>=p->rs485.drive_count)return ROBOT_PROFILE_BAD_REFERENCE;if(e->channel>1)return ROBOT_PROFILE_BAD_CHANNEL;if(!(e->capabilities&ROBOT_CAPABILITY_VELOCITY_RPM)||!(e->capabilities&ROBOT_CAPABILITY_STOPPABLE))return ROBOT_PROFILE_BAD_CAPABILITY;if(e->min_rpm>e->max_rpm||e->min_rpm>0||e->max_rpm<0||(float)e->max_rpm>p->max_wheel_rpm||(float)-e->min_rpm>p->max_wheel_rpm)return ROBOT_PROFILE_BAD_LIMIT;for(size_t j=0;j<i;j++)if(p->endpoints[j].id==e->id)return ROBOT_PROFILE_DUPLICATE_ID;}return ROBOT_PROFILE_VALID;}
static const robot_profile_t CURRENT={.schema_version=ROBOT_PROFILE_SCHEMA_VERSION,.name="current_robot",.rs485={.uart_port=2,.tx_pin=17,.rx_pin=16,.rts_pin=-1,.half_duplex=false,.baud_rate=115200,.response_timeout_ms=100,.retries=2,.telemetry_period_ms=30,.stale_timeout_ms=1000,.drive_count=2,.drive_ids={1,2}},.rc_uart_port=1,.rc_rx_pin=14,.steering_servo_pins={4,5,6,7},.steering_servos_enabled=false,.servo_min_us=1000,.servo_center_us=1500,.servo_max_us=2000,.servo_min_deg=-90.0f,.servo_max_deg=90.0f,.wheelbase_m=1.60f,.track_width_m=.70f,.wheel_radius_m=.10f,.max_wheel_rpm=15.0f,.endpoint_count=4,.endpoints={{1,"traction_front_left",0,0,0,3,ROBOT_ENDPOINT_REQUIRED,-15,15},{2,"traction_front_right",0,1,1,3,ROBOT_ENDPOINT_REQUIRED,-15,15},{3,"traction_rear_left",1,0,2,3,ROBOT_ENDPOINT_REQUIRED,-15,15},{4,"traction_rear_right",1,1,3,3,ROBOT_ENDPOINT_REQUIRED,-15,15}}};
const robot_profile_t*robot_profile_current(void){return &CURRENT;}
